import{_ as e,a as r,c as t,ac as s}from"./chunks/framework.BSuaGltH.js";const o=JSON.parse('{"title":"数组、链表与基础结构","description":"从按位置、节点和键访问数据出发，选择处理顺序、区间扫描与缓存结构；区分静态查询、批量更新和在线维护。","frontmatter":{"title":"数组、链表与基础结构","description":"从按位置、节点和键访问数据出发，选择处理顺序、区间扫描与缓存结构；区分静态查询、批量更新和在线维护。","generated":"consolidation-v2","showdocs":{"topics":[{"id":"data-structures","title":"数据结构","link":"/topics/data-structures/"},{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"系统学习","scope":"general","audience":"general","group":"原理与设计","summary":"从按位置、节点和键访问数据出发，选择处理顺序、区间扫描与缓存结构；区分静态查询、批量更新和在线维护。","status":"active","related":[{"title":"并查集","link":"/principles/data-structures/trees/union-find","kind":"系统学习","scope":"general","audience":"general"},{"title":"层序遍历","link":"/principles/data-structures/trees/tree-level-order","kind":"系统学习","scope":"general","audience":"general"},{"title":"差分数组","link":"/principles/data-structures/structures/difference-array","kind":"系统学习","scope":"general","audience":"general"},{"title":"堆","link":"/principles/data-structures/structures/heap","kind":"系统学习","scope":"general","audience":"general"},{"title":"队列","link":"/principles/data-structures/structures/queue","kind":"系统学习","scope":"general","audience":"general"}],"prev":{"text":"数组","link":"/principles/data-structures/structures/array"},"next":{"text":"双端队列","link":"/principles/data-structures/structures/deque"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"数组","link":"/principles/data-structures/structures/array"},"next":{"text":"双端队列","link":"/principles/data-structures/structures/deque"}},"headers":[],"relativePath":"principles/data-structures/structures/algorithms-structures-general-general.md","filePath":"principles/data-structures/structures/algorithms-structures-general-general.md"}'),n={name:"principles/data-structures/structures/algorithms-structures-general-general.md"};function p(d,a,i,c,l,u){return r(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="数组、链表与基础结构" tabindex="-1">数组、链表与基础结构 <a class="header-anchor" href="#数组、链表与基础结构" aria-label="Permalink to &quot;数组、链表与基础结构&quot;">​</a></h1><p>本页按场景选择方法；通过各条目链接阅读完整推演、源码和输出。</p><p>先掌握切片、指针和 map；下列每个 package main 单独保存为 main.go，使用独立模块，不能拼成一个文件。本轮仅静态推导输出。容器为单线程练习，MinHeap.Pop 与 Stack.Pop 都要求非空；区间操作要求 0 &lt;= l &lt;= r &lt;= n，整数累计须不溢出。</p><table tabindex="0"><thead><tr><th>要解决的问题</th><th>可选方法</th><th>选择前确认</th></tr></thead><tbody><tr><td>按下标读取或在中间插入</td><td><a href="#entry-array-8d5d6bffaf">数组</a>或<a href="#entry-linked-list-cbd6c10038">链表</a></td><td>数组访问 O(1) 但插入要移动；链表已知节点后插入 O(1)，按位置查找仍为 O(n)。</td></tr><tr><td>按到达顺序、反向顺序或优先级取元素</td><td><a href="#entry-queue-2524268d68">队列</a>、<a href="#entry-stack-927a66d593">栈</a>、<a href="#entry-deque-cdc32b59a6">双端队列</a>、<a href="#entry-heap-a02d7ab71b">堆</a></td><td>堆只保证根最小；队列需处理已消费空间，固定容量双端队列需检查空满。</td></tr><tr><td>按键统计或定位</td><td><a href="#entry-hash-map-a12cc84a51">哈希表</a></td><td>平均查找和更新 O(1)，遍历顺序未定义；稳定展示需排序键。</td></tr><tr><td>反复求静态区间和或批量做区间加法</td><td><a href="#entry-prefix-sum-9e7f942d55">前缀和</a>或<a href="#entry-difference-array-29d7f197d2">差分数组</a></td><td>前缀和适合静态查询；差分先记录全部更新再还原，不适合每次更新后立即查询。</td></tr><tr><td>避免重复扫描连续区间或配对</td><td><a href="#entry-sliding-window-b555b8bbbb">滑动窗口</a>或<a href="#entry-two-pointers-db6dbb6f28">双指针</a></td><td>示例窗口长度固定；目标和双指针要求数组有序，排序时须考虑原下标。</td></tr><tr><td>按最近使用顺序淘汰缓存，或分配分片归属</td><td><a href="#entry-lru-cache-eedfc2f646">LRU 缓存</a>或<a href="#entry-consistent-hashing-ff35d1c5cf">一致性哈希</a></td><td>LRU 的 map 与链表须同步；哈希环需注意节点分布不均和虚拟节点。</td></tr></tbody></table><h2 id="scene-address-data" tabindex="-1">按下标、节点、键或行列访问数据 <a class="header-anchor" href="#scene-address-data" aria-label="Permalink to &quot;按下标、节点、键或行列访问数据 {#scene-address-data}&quot;">​</a></h2><h3 id="entry-array-8d5d6bffaf" tabindex="-1">数组 <a class="header-anchor" href="#entry-array-8d5d6bffaf" aria-label="Permalink to &quot;数组 {#entry-array-8d5d6bffaf}&quot;">​</a></h3><p><span id="输出"></span><span id="示例"></span></p><p><span id="entry-array-8d5d6bffaf-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/structures/array">数组</a>。</p><p>Go 切片提供连续下标访问，append 可能因容量不足而分配新底层数组。示例先扩展长度，再用 copy 将插入位置后的元素右移。 按下标访问 O(1)，中间插入需移动元素，时间 O(n)。</p><p>插入下标必须在合法范围内；频繁在中间插入时，移动成本可能比查找成本更重要。</p><h3 id="entry-linked-list-cbd6c10038" tabindex="-1">链表 <a class="header-anchor" href="#entry-linked-list-cbd6c10038" aria-label="Permalink to &quot;链表 {#entry-linked-list-cbd6c10038}&quot;">​</a></h3><p><span id="输出-1"></span><span id="示例-1"></span></p><p><span id="entry-linked-list-cbd6c10038-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/structures/linked-list">链表</a>。</p><p>节点只保存值和下一个节点的指针，插入时改写相邻指针即可。示例已持有目标节点，因此操作不需要遍历；若只知道下标，仍要从头走到该位置。 已知节点后插入 O(1)，按位置查找 O(n)。</p><p>链表会产生额外指针与分配开销，Go 中普通顺序数据通常优先用切片。</p><h3 id="entry-hash-map-a12cc84a51" tabindex="-1">哈希表 <a class="header-anchor" href="#entry-hash-map-a12cc84a51" aria-label="Permalink to &quot;哈希表 {#entry-hash-map-a12cc84a51}&quot;">​</a></h3><p><span id="输出-2"></span><span id="示例-2"></span></p><p><span id="entry-hash-map-a12cc84a51-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/structures/hash-map">哈希表</a>。</p><p>Frequencies 用字符串作键，遇到一次就把计数加一。Go 的 map 在读取不存在的键时返回零值，因此无需预先插入每个单词。 查找与更新平均为 O(1)。</p><p>平均查找很快，但迭代顺序未定义；需要稳定输出时应先排序键。</p><h3 id="entry-matrix-traversal-72e54203af" tabindex="-1">矩阵遍历 <a class="header-anchor" href="#entry-matrix-traversal-72e54203af" aria-label="Permalink to &quot;矩阵遍历 {#entry-matrix-traversal-72e54203af}&quot;">​</a></h3><p><span id="输出-3"></span><span id="示例-3"></span></p><p><span id="entry-matrix-traversal-72e54203af-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/structures/matrix-traversal">矩阵遍历</a>。</p><p>涉及邻居搜索时还要检查行列边界，尤其是各行长度不同的情况。</p><h2 id="scene-choose-processing-order" tabindex="-1">控制先进先出、后进先出与优先级 <a class="header-anchor" href="#scene-choose-processing-order" aria-label="Permalink to &quot;控制先进先出、后进先出与优先级 {#scene-choose-processing-order}&quot;">​</a></h2><h3 id="entry-stack-927a66d593" tabindex="-1">栈 <a class="header-anchor" href="#entry-stack-927a66d593" aria-label="Permalink to &quot;栈 {#entry-stack-927a66d593}&quot;">​</a></h3><p><span id="输出-4"></span><span id="示例-4"></span></p><p><span id="entry-stack-927a66d593-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/structures/stack">栈</a>。</p><p>Push 把值附加到切片末尾，Pop 读取并删除最后一个值，保持后进先出。解析括号、深度优先搜索和撤销记录都可用栈。 尾部入栈摊还 O(1)。</p><p>示例假设弹出时非空；正式 API 应返回成功标记或错误，避免空栈越界。</p><h3 id="entry-queue-2524268d68" tabindex="-1">队列 <a class="header-anchor" href="#entry-queue-2524268d68" aria-label="Permalink to &quot;队列 {#entry-queue-2524268d68}&quot;">​</a></h3><p><span id="输出-5"></span><span id="示例-5"></span></p><p><span id="entry-queue-2524268d68-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/structures/queue">队列</a>。</p><p>长期运行时要定期压缩或重置底层切片，否则已消费的前段可能继续占内存。</p><h3 id="entry-deque-cdc32b59a6" tabindex="-1">双端队列 <a class="header-anchor" href="#entry-deque-cdc32b59a6" aria-label="Permalink to &quot;双端队列 {#entry-deque-cdc32b59a6}&quot;">​</a></h3><p><span id="输出-6"></span><span id="示例-6"></span></p><p><span id="entry-deque-cdc32b59a6-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/structures/deque">双端队列</a>。</p><p>环形缓冲区把逻辑位置映射到固定长度数组，front 左移即可在头部插入。尾部下标由 front 与 size 计算，两个方向都不必搬动已有元素。 两端都支持插入和取出。</p><p>这个示例要求容量大于零且未满；实际容器还需处理扩容和空队列。</p><h3 id="entry-heap-a02d7ab71b" tabindex="-1">堆 <a class="header-anchor" href="#entry-heap-a02d7ab71b" aria-label="Permalink to &quot;堆 {#entry-heap-a02d7ab71b}&quot;">​</a></h3><p><span id="输出-7"></span><span id="示例-7"></span></p><p><span id="entry-heap-a02d7ab71b-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/structures/heap">堆</a>。</p><p>最小堆只保证根是最小值，不保证整个切片有序。Push 沿父节点向上调整，Pop 把末尾元素放到根后沿较小子节点向下调整。 插入与取最小值都是 O(log n)。</p><p>优先队列和 Top K 常用堆；访问任意非根元素仍可能要线性查找。</p><h2 id="scene-range-aggregation" tabindex="-1">预处理区间和与批量区间更新 <a class="header-anchor" href="#scene-range-aggregation" aria-label="Permalink to &quot;预处理区间和与批量区间更新 {#scene-range-aggregation}&quot;">​</a></h2><h3 id="entry-prefix-sum-9e7f942d55" tabindex="-1">前缀和 <a class="header-anchor" href="#entry-prefix-sum-9e7f942d55" aria-label="Permalink to &quot;前缀和 {#entry-prefix-sum-9e7f942d55}&quot;">​</a></h3><p><span id="输出-8"></span><span id="示例-8"></span></p><p><span id="entry-prefix-sum-9e7f942d55-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/structures/prefix-sum">前缀和</a>。</p><p>它适合静态数据；频繁修改元素时应使用树状数组或线段树。</p><h3 id="entry-difference-array-29d7f197d2" tabindex="-1">差分数组 <a class="header-anchor" href="#entry-difference-array-29d7f197d2" aria-label="Permalink to &quot;差分数组 {#entry-difference-array-29d7f197d2}&quot;">​</a></h3><p><span id="输出-9"></span><span id="示例-9"></span></p><p><span id="entry-difference-array-29d7f197d2-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/structures/difference-array">差分数组</a>。</p><p>对 [l,r) 加 delta，只需在 l 处加 delta、r 处减 delta。所有更新记录完后做一次前缀累加，即可恢复每个位置的最终值。 n 个元素、q 次更新的总处理时间为 O(n+q)。</p><p>它适合离线批量更新；若更新之间要立即查询，应换用支持在线操作的数据结构。</p><h2 id="scene-scan-once" tabindex="-1">用指针和窗口减少重复扫描 <a class="header-anchor" href="#scene-scan-once" aria-label="Permalink to &quot;用指针和窗口减少重复扫描 {#scene-scan-once}&quot;">​</a></h2><h3 id="entry-two-pointers-db6dbb6f28" tabindex="-1">双指针 <a class="header-anchor" href="#entry-two-pointers-db6dbb6f28" aria-label="Permalink to &quot;双指针 {#entry-two-pointers-db6dbb6f28}&quot;">​</a></h3><p><span id="输出-10"></span><span id="示例-10"></span></p><p><span id="entry-two-pointers-db6dbb6f28-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/structures/two-pointers">双指针</a>。</p><p>有序数组的左右端相加后，和太小就移动左指针，太大就移动右指针。每一步都排除不可能的配对，因此只需线性扫描。 示例查找有序数组中的目标和。</p><p>输入无序时必须先排序或改用哈希表，并注意是否还需要原始下标。</p><h3 id="entry-sliding-window-b555b8bbbb" tabindex="-1">滑动窗口 <a class="header-anchor" href="#entry-sliding-window-b555b8bbbb" aria-label="Permalink to &quot;滑动窗口 {#entry-sliding-window-b555b8bbbb}&quot;">​</a></h3><p><span id="输出-11"></span><span id="示例-11"></span></p><p><span id="entry-sliding-window-b555b8bbbb-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/structures/sliding-window">滑动窗口</a>。</p><p>先计算第一个固定长度窗口的和，随后每右移一步只减去离开的元素并加上新进入的元素。这样避免重复求和，使整体复杂度降为 O(n)。 示例求长度为 k 的最大区间和，总时间 O(n)。</p><p>可变长度窗口需要明确扩张与收缩条件；这个示例只处理固定 k。</p><h2 id="scene-cache-and-shard" tabindex="-1">维护缓存淘汰顺序与分片归属 <a class="header-anchor" href="#scene-cache-and-shard" aria-label="Permalink to &quot;维护缓存淘汰顺序与分片归属 {#scene-cache-and-shard}&quot;">​</a></h2><h3 id="entry-lru-cache-eedfc2f646" tabindex="-1">LRU 缓存 <a class="header-anchor" href="#entry-lru-cache-eedfc2f646" aria-label="Permalink to &quot;LRU 缓存 {#entry-lru-cache-eedfc2f646}&quot;">​</a></h3><p><span id="输出-12"></span><span id="示例-12"></span></p><p><span id="entry-lru-cache-eedfc2f646-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/structures/lru-cache">LRU 缓存</a>。</p><p>map 让键能直接定位链表节点，链表头表示最近使用、尾部表示最久未使用。Get 与 Put 都把访问项移到头部；容量超限时删除尾节点。 Go 示例使用 container/list。</p><p>这里的 LRU 缓存用 map 定位 container/list 的节点。Get 命中和 Put 更新时调用链表的 MoveToFront，把节点移到最近使用端；淘汰时先删除 map 中的键，再用 Remove 删除同一尾节点，两个结构须保持一致。这两个方法属于链表，不是 LRU 自己新增的对外 API。</p><p>两个结构必须同步更新，否则会出现悬挂索引或错误淘汰。</p><h3 id="entry-consistent-hashing-ff35d1c5cf" tabindex="-1">一致性哈希 <a class="header-anchor" href="#entry-consistent-hashing-ff35d1c5cf" aria-label="Permalink to &quot;一致性哈希 {#entry-consistent-hashing-ff35d1c5cf}&quot;">​</a></h3><p><span id="输出-13"></span><span id="示例-13"></span></p><p><span id="entry-consistent-hashing-ff35d1c5cf-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/structures/consistent-hashing">一致性哈希</a>。</p><p>节点分布不均时会产生倾斜，实践中常为每个真实节点设置多个虚拟节点。</p><h2 id="review-exercise" tabindex="-1">静态自检 <a class="header-anchor" href="#review-exercise" aria-label="Permalink to &quot;静态自检 {#review-exercise}&quot;">​</a></h2><p>对容量为 2 的 LRU 依次 Put(a)、Put(b)、Get(a)、Put(c)，预测哪个键消失。提示：Get 也改变最近使用顺序。</p><details class="details custom-block"><summary>参考解法</summary><p>b 被淘汰；Get(a) 使 a 回到表头，随后新增 c 从尾部淘汰 b。仅调整 map、不同步移动或删除链表节点会破坏不变量。</p></details>',93)])])}const f=e(n,[["render",p]]);export{o as __pageData,f as default};
